  for (const store in data) {
    if (Array.isArray(data[store])) {
      await clearStore(store);
      await bulkPut(store, data[store]);
    }
  }
  if (syncChannel) {
    syncChannel.postMessage({ type: "DATABASE_RESET" });
  }
