function enqueueOutbox(item) {
  const rows = readLocalArray(outboxKey());
  const key3 = String(item?.key || "");
  if (key3 && rows.some((x) => x?.key === key3)) return;
  rows.push({ ...item, id: item?.id || `tgq-${Date.now()}-${Math.random().toString(36).slice(2, 7)}`, queuedAt: Date.now(), tries: 0 });
  writeLocalArray(outboxKey(), rows, OUTBOX_LIMIT);
}
function wasSent(key3) {
  if (!key3) return false;
  return readLocalArray(sentKey()).includes(key3);
}
function markSent(key3) {
  if (!key3) return;
  const rows = readLocalArray(sentKey()).filter((x) => x !== key3);
  rows.push(key3);
  writeLocalArray(sentKey(), rows, SENT_LIMIT);
}
async function deliverToRecipients(text, { settings = null, key: key3 = "", queueOnFailure = true, silent = false } = {}) {
  const config = settings || await getStoreSettings();
  const recipients = enabledRecipients(config);
  if (!recipients.length) return { ok: false, skipped: true, reason: "NO_RECIPIENTS", sent: 0, failed: 0 };
  if (key3 && wasSent(key3)) return { ok: true, duplicate: true, sent: 0, failed: 0 };
  let sent = 0;
  const failures = [];
  for (const recipient of recipients) {
    try {
      await sendTextToChat(recipient.chatId, text, { silent });
      sent += 1;
    } catch (error) {
      failures.push({ chatId: recipient.chatId, error: String(error?.message || error) });
    }
  }
  if (failures.length) {
    if (queueOnFailure) enqueueOutbox({ type: "broadcast", text, key: key3, silent, recipients: failures.map((x) => x.chatId) });
    return { ok: false, sent, failed: failures.length, failures };
  }
  if (key3) markSent(key3);
  return { ok: true, sent, failed: 0 };
}
async function flushTelegramOutbox() {
  if (flushing2) return { ok: false, busy: true };
  flushing2 = true;
  try {
    if (typeof navigator !== "undefined" && navigator.onLine === false) return { ok: false, offline: true };
    const settings = await getStoreSettings();
    if (!enabledRecipients(settings).length) return { ok: false, skipped: true };
    let queue = readLocalArray(outboxKey());
    const kept = [];
    let sent = 0;
    for (const item of queue) {
      if (!item?.text) continue;
      const targetRecipients = Array.isArray(item.recipients) && item.recipients.length ? normalizeTelegramRecipients(item.recipients.map((chatId) => ({ chatId, enabled: true }))).filter((r) => enabledRecipients(settings).some((active3) => active3.chatId === r.chatId)) : enabledRecipients(settings);
      const failedIds = [];
      for (const recipient of targetRecipients) {
        try {
          await sendTextToChat(recipient.chatId, item.text, { silent: !!item.silent });
        } catch {
          failedIds.push(recipient.chatId);
        }
      }
      if (failedIds.length) {
        kept.push({ ...item, recipients: failedIds, tries: asNumber(item.tries) + 1, lastTryAt: Date.now() });
      } else {
        sent += 1;
        if (item.key) markSent(item.key);
      }
    }
    writeLocalArray(outboxKey(), kept, OUTBOX_LIMIT);
    return { ok: kept.length === 0, sent, pending: kept.length };
  } finally {
    flushing2 = false;
  }
}
