var backfillLocalStockMetadata = async () => {
  try {
    const companyId = String(window.OscarActivation?.readRuntime?.()?.companyId || "local");
    const markerKey = `oscar-stock-meta-backfill-v109::${companyId}`;
    try {
      if (localStorage.getItem(markerKey) === "1") return false;
    } catch (_) {
    }
    const rows = await getAllFromStore("stock");
    if (!Array.isArray(rows) || !rows.length) {
      try {
        localStorage.setItem(markerKey, "1");
      } catch (_) {
      }
      return false;
    }
    const needsBackfill = rows.some((row2) => row2 && !row2.updatedAt);
    if (!needsBackfill) {
      try {
        localStorage.setItem(markerKey, "1");
      } catch (_) {
      }
      return false;
    }
    const patched = [];
    const legacyRows = rows.filter((row2) => row2 && !row2.updatedAt);
    for (let i = 0; i < legacyRows.length; i += 12) {
      const batch = legacyRows.slice(i, i + 12);
      const resolved = await Promise.all(batch.map(async (row2) => ({
        row: row2,
        mov: await getLatestStockMovementLocal(row2.productId, row2.warehouseId).catch(() => null)
      })));
      for (const { row: row2, mov } of resolved) {
        if (!mov) continue;
        const time = new Date(mov.date || mov.createdAt || 0).getTime();
        if (!Number.isFinite(time) || time <= 0) continue;
        const next = { ...row2, updatedAt: new Date(time).toISOString() };
        const movementBalance = Number(mov?.newBaseBalance);
        const rowBalance = Number(row2.baseQuantity);
        if (Number.isFinite(movementBalance) && Number.isFinite(rowBalance) && Math.abs(movementBalance - rowBalance) < 1e-6) {
          next.balanceVerifiedByMovement = true;
        }
        patched.push(next);
      }
    }
    if (patched.length) await bulkPut("stock", patched, false);
    try {
      localStorage.setItem(markerKey, "1");
    } catch (_) {
    }
    return patched.length > 0;
  } catch (_) {
    return false;
  }
};
